class Node:
    def __init__(self, val):
        self.val = val
        self.next = None


class LinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.len = 0

    def append(self, val):
        new_node = Node(val)
        if self.head == None:
            self.head = new_node
            self.tail = new_node
        else:
            self.tail.next = new_node
            self.tail = new_node
        self.len += 1

    def delete(self, index):
        if index == 0:
            val = self.head.val
            self.head = self.head.next
            if self.len == 1:
                self.tail = None
        else:
            run_node = self.head
            for i in range(index - 1):
                run_node = run_node.next
            val = run_node.next.val
            run_node.next = run_node.next.next
            if index == self.len - 1:
                self.tail = run_node
        self.len -= 1
        return val


